//
//  LayoutBreadcrumbs.Routes.swift
//  TeslaSync — P4 shared surface · 0170 · LayoutBreadcrumbs (Apple)
//
//  The route catalog — the native peer of the web `ROUTE_META` map (lib/routeMeta.ts) that
//  `useBreadcrumbs` walks to compose the trail. The web `ROUTE_META` is derived from the autogenerated
//  `ROUTE_REGISTRY` (lib/routeRegistry.ts) — every registered frontend route gets a baseline breadcrumb
//  entry (its i18n key + English fallback label) — merged with the explicit `PARENT_OVERRIDES` that opt a
//  nested / detail route into a parent chain. This file ports both verbatim: all 113 registered routes in
//  the same declaration order (so "the first registered pattern that matches" resolves identically to the
//  web `Object.keys(ROUTE_META)` iteration) and the 12 parent links that make a route render a >= 2-item
//  trail. Everything else is a single-item entry that ``BreadcrumbOverridesTrailView`` self-suppresses,
//  exactly like the web top-level pages.
//
//  The entries are DATA (kept in sync with the generated web registry), not i18n keys themselves — the
//  `i18nKey` column is resolved at the display boundary through the app catalog with the English label as
//  the fallback (web `t(meta.i18nKey, meta.defaultLabel)`), wired by ``LayoutBreadcrumbsStrings/routeLabel``.
//

import Foundation

// MARK: - LayoutBreadcrumbsRouteCatalog (web ROUTE_META = ROUTE_REGISTRY + PARENT_OVERRIDES)

