    public static let table = BreadcrumbOverridesRouteTable(entries)

    /// Compact factory keeping each catalog row on one line within the line-length budget — `pattern`,
    /// `i18nKey`, English `defaultLabel`, and the optional `parent` pattern (web `PARENT_OVERRIDES`).
    private static func route(
        _ pattern: String,
        _ i18nKey: String,
        _ defaultLabel: String,
        parent: String? = nil
    ) -> BreadcrumbOverridesRouteMeta {
        BreadcrumbOverridesRouteMeta(
            pattern: pattern,
            i18nKey: i18nKey,
            defaultLabel: defaultLabel,
            parent: parent
        )
